import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ProcessedImage {
  blob: Blob;
  url: string;
  size: number;
  width: number;
  height: number;
}

export interface ImageSettings {
  quality: number; // 0 to 1
  scale: number; // 0.1 to 2
  format: 'image/jpeg' | 'image/png' | 'image/webp';
}

export enum AppMode {
  COMPRESS = 'COMPRESS',
  ENHANCE = 'ENHANCE',
}

import { ImageSettings, ProcessedImage } from '../types';

export const processImageClientSide = async (
  file: File,
  settings: ImageSettings
): Promise<ProcessedImage> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const objectUrl = URL.createObjectURL(file);

    img.onload = () => {
      URL.revokeObjectURL(objectUrl);
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        reject(new Error('Could not get canvas context'));
        return;
      }

      // Calculate new dimensions
      const targetWidth = Math.max(1, Math.floor(img.width * settings.scale));
      const targetHeight = Math.max(1, Math.floor(img.height * settings.scale));

      canvas.width = targetWidth;
      canvas.height = targetHeight;

      // Draw and resize
      // Better quality resizing algorithm could be implemented here (e.g. stepping)
      // for severe downscaling, but drawImage is usually sufficient for simple tools.
      ctx.drawImage(img, 0, 0, targetWidth, targetHeight);

      // Export
      canvas.toBlob(
        (blob) => {
          if (!blob) {
            reject(new Error('Canvas to Blob failed'));
            return;
          }
          const url = URL.createObjectURL(blob);
          resolve({
            blob,
            url,
            size: blob.size,
            width: targetWidth,
            height: targetHeight,
          });
        },
        settings.format,
        settings.quality
      );
    };

    img.onerror = (err) => {
      URL.revokeObjectURL(objectUrl);
      reject(err);
    };

    img.src = objectUrl;
  });
};

export const formatBytes = (bytes: number, decimals = 2) => {
  if (bytes === 0) return '0 Bytes';
  const k = 1024;
  const dm = decimals < 0 ? 0 : decimals;
  const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
};

export const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      // Remove data url prefix (e.g., "data:image/jpeg;base64,")
      const base64Data = base64String.split(',')[1];
      resolve(base64Data);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

import { GoogleGenAI } from "@google/genai";
import { blobToBase64 } from './imageProcessing';

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const enhanceImageWithGemini = async (
  imageFile: File,
  promptText: string
): Promise<string> => {
  try {
    const base64Data = await blobToBase64(imageFile);

    // Using gemini-2.5-flash-image for speed and efficiency in generating/editing
    const model = 'gemini-2.5-flash-image';

    const response = await ai.models.generateContent({
      model: model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: imageFile.type,
              data: base64Data,
            },
          },
          {
            text: `${promptText}. Return only the image.`,
          },
        ],
      },
    });

    // Extract image from response
    // The model might return a text description AND an image, or just an image.
    const candidates = response.candidates;
    if (!candidates || candidates.length === 0) {
      throw new Error("No response from AI");
    }

    const parts = candidates[0].content.parts;
    let imageUrl = '';

    for (const part of parts) {
      if (part.inlineData && part.inlineData.data) {
        imageUrl = `data:image/png;base64,${part.inlineData.data}`;
        break;
      }
    }

    if (!imageUrl) {
      throw new Error("AI did not generate an image. It might have only returned text.");
    }

    return imageUrl;

  } catch (error) {
    console.error("Gemini Enhancement Error:", error);
    throw error;
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  disabled,
  ...props 
}) => {
  const baseStyles = "px-4 py-2 rounded-lg font-medium transition-all duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-primary hover:bg-secondary text-white shadow-lg shadow-primary/30",
    secondary: "bg-surface hover:bg-gray-700 text-gray-200 border border-gray-600",
    danger: "bg-red-500 hover:bg-red-600 text-white",
    ghost: "bg-transparent hover:bg-gray-800 text-gray-400 hover:text-white"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`}
      disabled={disabled || isLoading}
      {...props}
    >
      {isLoading && (
        <svg className="animate-spin h-5 w-5 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
      )}
      {children}
    </button>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { ImageSettings, ProcessedImage } from '../types';
import { processImageClientSide, formatBytes } from '../services/imageProcessing';
import { Button } from './Button';

interface CompressorProps {
  originalFile: File;
}

export const Compressor: React.FC<CompressorProps> = ({ originalFile }) => {
  const [settings, setSettings] = useState<ImageSettings>({
    quality: 0.8,
    scale: 1,
    format: originalFile.type === 'image/png' ? 'image/png' : 'image/jpeg' as any,
  });

  const [processed, setProcessed] = useState<ProcessedImage | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // Debounced processing to avoid freezing UI while sliding
  const process = useCallback(async () => {
    setIsProcessing(true);
    try {
      const result = await processImageClientSide(originalFile, settings);
      setProcessed(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  }, [originalFile, settings]);

  useEffect(() => {
    const timer = setTimeout(() => {
      process();
    }, 300); // 300ms debounce
    return () => clearTimeout(timer);
  }, [process]);

  const handleDownload = () => {
    if (!processed) return;
    const link = document.createElement('a');
    link.href = processed.url;
    link.download = `optimized_${originalFile.name.split('.')[0]}.${settings.format.split('/')[1]}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-full">
      {/* Controls */}
      <div className="w-full lg:w-1/3 bg-surface p-6 rounded-2xl border border-gray-700 flex flex-col gap-6">
        <div>
          <h3 className="text-xl font-bold mb-4 text-white">Tùy chỉnh nén</h3>

          <div className="space-y-6">
            <div>
              <div className="flex justify-between mb-2">
                <label className="text-sm font-medium text-gray-300">Chất lượng</label>
                <span className="text-sm text-primary font-bold">{Math.round(settings.quality * 100)}%</span>
              </div>
              <input
                type="range"
                min="0.1"
                max="1"
                step="0.05"
                value={settings.quality}
                onChange={(e) => setSettings({ ...settings, quality: parseFloat(e.target.value) })}
                className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-primary"
              />
            </div>

            <div>
              <div className="flex justify-between mb-2">
                <label className="text-sm font-medium text-gray-300">Kích thước (Scale)</label>
                <span className="text-sm text-primary font-bold">{Math.round(settings.scale * 100)}%</span>
              </div>
              <input
                type="range"
                min="0.1"
                max="1"
                step="0.1"
                value={settings.scale}
                onChange={(e) => setSettings({ ...settings, scale: parseFloat(e.target.value) })}
                className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-primary"
              />
            </div>

            <div>
              <label className="text-sm font-medium text-gray-300 mb-2 block">Định dạng</label>
              <div className="flex gap-2 p-1 bg-gray-900 rounded-lg">
                {(['image/jpeg', 'image/png', 'image/webp'] as const).map((fmt) => (
                  <button
                    key={fmt}
                    onClick={() => setSettings({ ...settings, format: fmt })}
                    className={`flex-1 py-2 text-xs font-bold rounded-md transition-colors ${
                      settings.format === fmt 
                        ? 'bg-primary text-white shadow' 
                        : 'text-gray-400 hover:text-white'
                    }`}
                  >
                    {fmt.split('/')[1].toUpperCase()}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>

        <div className="mt-auto pt-6 border-t border-gray-700">
           <div className="flex justify-between items-center mb-4">
              <span className="text-gray-400">Gốc:</span>
              <span className="font-mono text-white">{formatBytes(originalFile.size)}</span>
           </div>
           <div className="flex justify-between items-center mb-6">
              <span className="text-gray-400">Sau khi nén:</span>
              <span className={`font-mono font-bold ${processed && processed.size < originalFile.size ? 'text-green-400' : 'text-yellow-400'}`}>
                {processed ? formatBytes(processed.size) : '...'}
              </span>
           </div>

           <Button 
            onClick={handleDownload} 
            disabled={!processed} 
            className="w-full"
           >
            Tải xuống
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
            </svg>
           </Button>
        </div>
      </div>

      {/* Preview */}
      <div className="flex-1 bg-gray-900/50 rounded-2xl flex items-center justify-center p-4 border border-dashed border-gray-700 relative overflow-hidden group">
        {!processed && isProcessing && (
          <div className="absolute inset-0 flex items-center justify-center bg-dark/50 z-10">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          </div>
        )}
        {processed ? (
          <div className="relative max-w-full max-h-full">
            <img 
              src={processed.url} 
              alt="Processed" 
              className="max-w-full max-h-[70vh] object-contain rounded-lg shadow-2xl" 
            />
            <div className="absolute bottom-4 right-4 bg-black/70 backdrop-blur text-white text-xs px-2 py-1 rounded">
              {processed.width} x {processed.height} px
            </div>
          </div>
        ) : (
           <span className="text-gray-500">Đang xử lý...</span>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { enhanceImageWithGemini } from '../services/geminiService';
import { Button } from './Button';

interface AIEnhancerProps {
  originalFile: File;
}

export const AIEnhancer: React.FC<AIEnhancerProps> = ({ originalFile }) => {
  const [resultUrl, setResultUrl] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [customPrompt, setCustomPrompt] = useState("");
  const [mode, setMode] = useState<'restore' | 'creative'>('restore');

  const handleEnhance = async () => {
    setIsProcessing(true);
    setError(null);
    setResultUrl(null);

    try {
      let prompt = "";
      if (mode === 'restore') {
        prompt = "Enhance the quality of this image. Increase sharpness, improve lighting, remove noise, and make it look high resolution and photorealistic. Maintain the original subject matter and composition exactly.";
      } else {
        prompt = customPrompt || "Make this image look like a high-budget cinematic movie shot. Enhance details and colors significantly.";
      }

      const url = await enhanceImageWithGemini(originalFile, prompt);
      setResultUrl(url);
    } catch (err) {
      setError("Có lỗi xảy ra khi xử lý với AI. Vui lòng thử lại.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDownload = () => {
    if (!resultUrl) return;
    const link = document.createElement('a');
    link.href = resultUrl;
    link.download = `ai_enhanced_${originalFile.name.split('.')[0]}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-full">
       {/* Sidebar */}
       <div className="w-full lg:w-1/3 bg-surface p-6 rounded-2xl border border-gray-700 flex flex-col gap-6">
          <div>
            <h3 className="text-xl font-bold mb-2 text-white">AI Nâng cấp ảnh</h3>
            <p className="text-xs text-gray-400 mb-6">Sử dụng Gemini 2.5 Flash Image để tái tạo và nâng cấp hình ảnh.</p>

            <div className="space-y-4">
              <div className="flex gap-2 p-1 bg-gray-900 rounded-lg">
                <button
                  onClick={() => setMode('restore')}
                  className={`flex-1 py-2 text-xs font-bold rounded-md transition-colors ${mode === 'restore' ? 'bg-primary text-white' : 'text-gray-400'}`}
                >
                  Phục hồi & Nét
                </button>
                <button
                  onClick={() => setMode('creative')}
                  className={`flex-1 py-2 text-xs font-bold rounded-md transition-colors ${mode === 'creative' ? 'bg-purple-600 text-white' : 'text-gray-400'}`}
                >
                  Sáng tạo
                </button>
              </div>

              {mode === 'creative' && (
                <div>
                  <label className="text-sm text-gray-300 block mb-2">Mô tả thay đổi (Tiếng Anh)</label>
                  <textarea
                    className="w-full bg-gray-900 border border-gray-700 rounded-lg p-3 text-sm text-white focus:border-primary focus:ring-1 focus:ring-primary outline-none"
                    rows={4}
                    placeholder="E.g., Make it look like a oil painting, add cyberpunk lighting..."
                    value={customPrompt}
                    onChange={(e) => setCustomPrompt(e.target.value)}
                  />
                </div>
              )}

              {mode === 'restore' && (
                 <div className="p-3 bg-gray-800/50 rounded-lg border border-gray-700">
                    <p className="text-xs text-gray-300 italic">
                      Chế độ này sẽ cố gắng giữ nguyên bố cục nhưng tăng độ nét và giảm nhiễu hạt.
                    </p>
                 </div>
              )}
            </div>
          </div>

          <div className="mt-auto">
            {error && (
              <div className="mb-4 p-3 bg-red-900/50 border border-red-500/50 rounded-lg text-red-200 text-xs">
                {error}
              </div>
            )}
            <Button 
              onClick={handleEnhance} 
              isLoading={isProcessing} 
              variant={mode === 'creative' ? 'secondary' : 'primary'}
              className="w-full mb-3"
            >
              {isProcessing ? 'Đang phân tích...' : 'Bắt đầu xử lý'}
            </Button>

            {resultUrl && (
              <Button onClick={handleDownload} variant="ghost" className="w-full border border-gray-600">
                Tải xuống ảnh AI
              </Button>
            )}
          </div>
       </div>

       {/* Comparison View */}
       <div className="flex-1 flex flex-col gap-4">
          <div className="h-1/2 bg-gray-900/50 rounded-xl p-4 border border-gray-700 relative flex flex-col">
            <span className="absolute top-2 left-2 bg-black/60 text-white text-[10px] px-2 py-1 rounded">Gốc</span>
            <div className="flex-1 flex items-center justify-center overflow-hidden">
               <img 
                  src={URL.createObjectURL(originalFile)} 
                  alt="Original" 
                  className="max-h-full object-contain" 
                  onLoad={(e) => URL.revokeObjectURL((e.target as HTMLImageElement).src)}
                />
            </div>
          </div>

          <div className="h-1/2 bg-gray-900/50 rounded-xl p-4 border border-gray-700 border-dashed relative flex flex-col items-center justify-center">
             <span className="absolute top-2 left-2 bg-primary/80 text-white text-[10px] px-2 py-1 rounded">Kết quả AI</span>
             {isProcessing ? (
               <div className="flex flex-col items-center gap-3">
                 <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin"></div>
                 <p className="text-xs text-gray-400 animate-pulse">Gemini đang vẽ lại ảnh của bạn...</p>
               </div>
             ) : resultUrl ? (
                <img 
                  src={resultUrl} 
                  alt="AI Enhanced" 
                  className="max-h-full object-contain rounded shadow-lg" 
                />
             ) : (
               <p className="text-gray-500 text-sm">Kết quả sẽ hiện ở đây</p>
             )}
          </div>
       </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { AppMode } from './types';
import { Compressor } from './components/Compressor';
import { AIEnhancer } from './components/AIEnhancer';

function App() {
  const [file, setFile] = useState<File | null>(null);
  const [mode, setMode] = useState<AppMode>(AppMode.COMPRESS);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleReset = () => {
    setFile(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  return (
    <div className="min-h-screen bg-dark text-gray-100 p-4 md:p-8">
      <div className="max-w-7xl mx-auto h-[calc(100vh-4rem)] flex flex-col">
        {/* Header */}
        <header className="flex justify-between items-center mb-8">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-primary to-purple-600 rounded-xl flex items-center justify-center shadow-lg shadow-primary/20">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight text-white">OptiPlex</h1>
              <p className="text-xs text-gray-400">Studio hình ảnh thông minh</p>
            </div>
          </div>

          {file && (
             <button 
                onClick={handleReset}
                className="text-sm text-gray-400 hover:text-white transition-colors flex items-center gap-2"
             >
               <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                 <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
               </svg>
               Chọn ảnh khác
             </button>
          )}
        </header>

        {/* Content */}
        {!file ? (
          <div className="flex-1 flex flex-col items-center justify-center bg-surface/30 border-2 border-dashed border-gray-700 rounded-3xl p-12 text-center transition-all hover:border-primary/50 group cursor-pointer relative">
            <input 
               type="file" 
               accept="image/*"
               onChange={handleFileChange}
               ref={fileInputRef}
               className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            />
            <div className="w-20 h-20 bg-gray-800 rounded-full flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-300 shadow-xl">
               <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-primary" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
               </svg>
            </div>
            <h2 className="text-2xl font-bold text-white mb-2">Tải ảnh lên</h2>
            <p className="text-gray-400 max-w-sm mx-auto">
              Hỗ trợ PNG, JPG, WEBP. <br/>Kéo thả hoặc nhấn vào đây để bắt đầu.
            </p>
          </div>
        ) : (
          <div className="flex-1 flex flex-col overflow-hidden">
            {/* Tabs */}
            <div className="flex gap-4 mb-6 border-b border-gray-800 pb-1">
               <button
                  onClick={() => setMode(AppMode.COMPRESS)}
                  className={`pb-3 px-4 text-sm font-bold border-b-2 transition-all ${
                     mode === AppMode.COMPRESS 
                     ? 'border-primary text-primary' 
                     : 'border-transparent text-gray-400 hover:text-gray-200'
                  }`}
               >
                  Nén & Resize
               </button>
               <button
                  onClick={() => setMode(AppMode.ENHANCE)}
                  className={`pb-3 px-4 text-sm font-bold border-b-2 transition-all flex items-center gap-2 ${
                     mode === AppMode.ENHANCE 
                     ? 'border-purple-500 text-purple-400' 
                     : 'border-transparent text-gray-400 hover:text-gray-200'
                  }`}
               >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M5 2a1 1 0 011 1v1h1a1 1 0 010 2H6v1a1 1 0 01-2 0V6H3a1 1 0 010-2h1V3a1 1 0 011-1zm0 10a1 1 0 011 1v1h1a1 1 0 110 2H6v1a1 1 0 11-2 0v-1H3a1 1 0 110-2h1v-1a1 1 0 011-1zM12 2a1 1 0 01.967.744L14.146 7.2 17.5 9.134a1 1 0 010 1.732l-3.354 1.935-1.18 4.455a1 1 0 01-1.933 0L9.854 12.8 6.5 10.866a1 1 0 010-1.732l3.354-1.935 1.18-4.455A1 1 0 0112 2z" clipRule="evenodd" />
                  </svg>
                  AI Nâng cao (Gemini)
               </button>
            </div>

            {/* Workspace */}
            <div className="flex-1 min-h-0">
               {mode === AppMode.COMPRESS ? (
                  <Compressor originalFile={file} />
               ) : (
