export interface ProcessedImage {
  blob: Blob;
  url: string;
  size: number;
  width: number;
  height: number;
}

export interface CropConfig {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface ImageSettings {
  quality: number; // 0 to 1
  scale: number; // 0.1 to 2
  format: 'image/jpeg' | 'image/png' | 'image/webp';
  rotation: number; // degrees
  crop?: CropConfig;
}

export enum AppMode {
  COMPRESS = 'COMPRESS',
  ENHANCE = 'ENHANCE',
}

import { ImageSettings, ProcessedImage } from '../types';

export const processImageClientSide = async (
  file: File,
  settings: ImageSettings
): Promise<ProcessedImage> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const objectUrl = URL.createObjectURL(file);

    img.onload = () => {
      URL.revokeObjectURL(objectUrl);
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        reject(new Error('Could not get canvas context'));
        return;
      }

      // 1. Determine Crop Area (Source)
      const cropX = settings.crop ? settings.crop.x : 0;
      const cropY = settings.crop ? settings.crop.y : 0;
      const cropW = settings.crop ? settings.crop.width : img.width;
      const cropH = settings.crop ? settings.crop.height : img.height;

      // Ensure crop is within bounds (sanity check)
      const safeCropX = Math.max(0, cropX);
      const safeCropY = Math.max(0, cropY);
      const safeCropW = Math.min(cropW, img.width - safeCropX);
      const safeCropH = Math.min(cropH, img.height - safeCropY);

      // 2. Calculate dimensions of the rotated crop
      // We need the bounding box size of the rotated rectangle
      const angleRad = (settings.rotation * Math.PI) / 180;
      const absCos = Math.abs(Math.cos(angleRad));
      const absSin = Math.abs(Math.sin(angleRad));

      const rotatedWidth = safeCropW * absCos + safeCropH * absSin;
      const rotatedHeight = safeCropW * absSin + safeCropH * absCos;

      // 3. Apply Scale to determine final canvas size
      const targetWidth = Math.max(1, Math.floor(rotatedWidth * settings.scale));
      const targetHeight = Math.max(1, Math.floor(rotatedHeight * settings.scale));

      canvas.width = targetWidth;
      canvas.height = targetHeight;

      // 4. Draw
      // Move context to center to handle rotation
      ctx.translate(targetWidth / 2, targetHeight / 2);
      ctx.rotate(angleRad);

      // We are drawing the cropped area, centered.
      // The drawing size needs to be scaled.
      const scaledDrawW = safeCropW * settings.scale;
      const scaledDrawH = safeCropH * settings.scale;

      // Draw image
      // Source coords: safeCropX, safeCropY, safeCropW, safeCropH
      // Dest coords: -width/2, -height/2 (relative to rotated center)
      ctx.drawImage(
        img, 
        safeCropX, safeCropY, safeCropW, safeCropH, 
        -scaledDrawW / 2, -scaledDrawH / 2, scaledDrawW, scaledDrawH
      );

      // Export
      canvas.toBlob(
        (blob) => {
          if (!blob) {
            reject(new Error('Canvas to Blob failed'));
            return;
          }
          const url = URL.createObjectURL(blob);
          resolve({
            blob,
            url,
            size: blob.size,
            width: targetWidth,
            height: targetHeight,
          });
        },
        settings.format,
        settings.quality
      );
    };

    img.onerror = (err) => {
      URL.revokeObjectURL(objectUrl);
      reject(err);
    };

    img.src = objectUrl;
  });
};

export const formatBytes = (bytes: number, decimals = 2) => {
  if (bytes === 0) return '0 Bytes';
  const k = 1024;
  const dm = decimals < 0 ? 0 : decimals;
  const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
};

export const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      resolve(base64Data);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

import React, { useState, useEffect, useCallback } from 'react';
import { ImageSettings, ProcessedImage, CropConfig } from '../types';
import { processImageClientSide, formatBytes } from '../services/imageProcessing';
import { Button } from './Button';

interface CompressorProps {
  originalFile: File;
}

export const Compressor: React.FC<CompressorProps> = ({ originalFile }) => {
  // Store original image dimensions to calculate crop percentages to pixels
  const [originalDimensions, setOriginalDimensions] = useState<{w: number, h: number} | null>(null);

  const [settings, setSettings] = useState<ImageSettings>({
    quality: 0.8,
    scale: 1,
    format: originalFile.type === 'image/png' ? 'image/png' : 'image/jpeg' as any,
    rotation: 0,
    crop: undefined,
  });

  // UI state for Crop
  const [isCropOpen, setIsCropOpen] = useState(false);
  const [cropInsets, setCropInsets] = useState({ top: 0, bottom: 0, left: 0, right: 0 }); // Percentages 0-100

  const [processed, setProcessed] = useState<ProcessedImage | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // Load image dimensions when file changes
  useEffect(() => {
    const img = new Image();
    const url = URL.createObjectURL(originalFile);
    img.onload = () => {
      setOriginalDimensions({ w: img.width, h: img.height });
      URL.revokeObjectURL(url);
    };
    img.src = url;

    // Reset settings
    setSettings({
        quality: 0.8,
        scale: 1,
        format: originalFile.type === 'image/png' ? 'image/png' : 'image/jpeg' as any,
        rotation: 0,
        crop: undefined
    });
    setCropInsets({ top: 0, bottom: 0, left: 0, right: 0 });
    setIsCropOpen(false);
  }, [originalFile]);

  // Update settings.crop when insets change
  useEffect(() => {
    if (!originalDimensions) return;

    if (cropInsets.top === 0 && cropInsets.bottom === 0 && cropInsets.left === 0 && cropInsets.right === 0) {
        setSettings(s => ({ ...s, crop: undefined }));
        return;
    }

    const x = Math.floor(originalDimensions.w * (cropInsets.left / 100));
    const y = Math.floor(originalDimensions.h * (cropInsets.top / 100));
    const width = Math.floor(originalDimensions.w * (1 - (cropInsets.left + cropInsets.right) / 100));
    const height = Math.floor(originalDimensions.h * (1 - (cropInsets.top + cropInsets.bottom) / 100));

    // Valid check
    if (width > 0 && height > 0) {
        const newCrop: CropConfig = { x, y, width, height };
        setSettings(s => ({ ...s, crop: newCrop }));
    }
  }, [cropInsets, originalDimensions]);

  // Debounced processing
  const process = useCallback(async () => {
    setIsProcessing(true);
    try {
      const result = await processImageClientSide(originalFile, settings);
      setProcessed(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  }, [originalFile, settings]);

  useEffect(() => {
    const timer = setTimeout(() => {
      process();
    }, 300); // 300ms debounce
    return () => clearTimeout(timer);
  }, [process]);

  const handleDownload = () => {
    if (!processed) return;
    const link = document.createElement('a');
    link.href = processed.url;
    link.download = `optimized_${originalFile.name.split('.')[0]}.${settings.format.split('/')[1]}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-full">
      {/* Controls */}
      <div className="w-full lg:w-1/3 bg-surface p-6 rounded-2xl border border-gray-700 flex flex-col gap-6 overflow-y-auto max-h-[calc(100vh-10rem)]">

        {/* Edit Section */}
        <div>
           <h3 className="text-xl font-bold mb-4 text-white flex items-center gap-2">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-primary" viewBox="0 0 20 20" fill="currentColor">
               <path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" />
             </svg>
             Chỉnh sửa
           </h3>
           <div className="space-y-4 bg-gray-900/50 p-4 rounded-xl border border-gray-700/50">

              {/* Rotation */}
              <div>
                 <label className="text-sm font-medium text-gray-300 mb-2 block">Góc xoay (độ)</label>
                 <div className="flex gap-2">
                    <input 
                       type="number" 
                       value={settings.rotation} 
                       onChange={(e) => setSettings({...settings, rotation: Number(e.target.value)})}
                       className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-white focus:ring-1 focus:ring-primary outline-none"
                    />
                    <div className="flex gap-1">
                        <button onClick={() => setSettings(s => ({...s, rotation: s.rotation - 90}))} className="bg-gray-700 hover:bg-gray-600 text-white p-2 rounded-lg" title="-90 độ">↺</button>
                        <button onClick={() => setSettings(s => ({...s, rotation: s.rotation + 90}))} className="bg-gray-700 hover:bg-gray-600 text-white p-2 rounded-lg" title="+90 độ">↻</button>
                    </div>
                 </div>
              </div>

              {/* Crop Toggle */}
              <div>
                 <button 
                    onClick={() => setIsCropOpen(!isCropOpen)}
                    className={`w-full py-2 rounded-lg font-medium text-sm transition-colors border ${isCropOpen ? 'bg-primary text-white border-primary' : 'bg-transparent text-gray-300 border-gray-600 hover:border-gray-400'}`}
                 >
                    {isCropOpen ? 'Đóng công cụ cắt' : 'Cắt ảnh (Crop)'}
                 </button>

                 {isCropOpen && (
                    <div className="mt-4 space-y-3 animate-in fade-in slide-in-from-top-2">
                       <p className="text-xs text-gray-400 italic">Kéo thanh trượt để cắt bỏ phần thừa từ các cạnh (%)</p>

                       {[
                         { label: 'Trên', key: 'top' },
                         { label: 'Dưới', key: 'bottom' },
                         { label: 'Trái', key: 'left' },
                         { label: 'Phải', key: 'right' }
                       ].map((side) => (
                          <div key={side.key} className="flex items-center gap-3">
                             <label className="text-xs text-gray-400 w-8">{side.label}</label>
                             <input 
                                type="range" 
                                min="0" 
                                max="45" 
                                step="1"
                                value={(cropInsets as any)[side.key]} 
                                onChange={(e) => setCropInsets({...cropInsets, [side.key]: Number(e.target.value)})}
                                className="flex-1 h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-primary"
                             />
                             <span className="text-xs text-white w-8 text-right">{(cropInsets as any)[side.key]}%</span>
                          </div>
                       ))}
                       <button 
                          onClick={() => setCropInsets({top: 0, bottom: 0, left: 0, right: 0})}
                          className="text-xs text-red-400 hover:text-red-300 w-full text-right mt-2"
                        >
                          Đặt lại cắt
                        </button>
                    </div>
                 )}
              </div>
           </div>
        </div>

        {/* Compression Section */}
        <div>
          <h3 className="text-xl font-bold mb-4 text-white flex items-center gap-2">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-primary" viewBox="0 0 20 20" fill="currentColor">
               <path fillRule="evenodd" d="M4 2a2 2 0 00-2 2v11a3 3 0 106 0V4a2 2 0 00-2-2H4zm1 14a1 1 0 100-2 1 1 0 000 2zm5-1.757l4.9-4.9a2 2 0 000-2.828L13.485 5.1a2 2 0 00-2.828 0L10 5.757v8.486zM16 18H9.071l6-6H16a2 2 0 012 2v2a2 2 0 01-2 2z" clipRule="evenodd" />
            </svg>
            Tùy chỉnh nén
          </h3>

          <div className="space-y-6">
            <div>
              <div className="flex justify-between mb-2">
                <label className="text-sm font-medium text-gray-300">Chất lượng</label>
                <span className="text-sm text-primary font-bold">{Math.round(settings.quality * 100)}%</span>
              </div>
              <input
                type="range"
                min="0.1"
                max="1"
                step="0.05"
                value={settings.quality}
                onChange={(e) => setSettings({ ...settings, quality: parseFloat(e.target.value) })}
                className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-primary"
              />
            </div>

            <div>
              <div className="flex justify-between mb-2">
                <label className="text-sm font-medium text-gray-300">Kích thước (Scale)</label>
                <span className="text-sm text-primary font-bold">{Math.round(settings.scale * 100)}%</span>
              </div>
              <input
                type="range"
                min="0.1"
                max="1"
                step="0.1"
                value={settings.scale}
                onChange={(e) => setSettings({ ...settings, scale: parseFloat(e.target.value) })}
                className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-primary"
              />
            </div>

            <div>
              <label className="text-sm font-medium text-gray-300 mb-2 block">Định dạng</label>
              <div className="flex gap-2 p-1 bg-gray-900 rounded-lg">
                {(['image/jpeg', 'image/png', 'image/webp'] as const).map((fmt) => (
                  <button
                    key={fmt}
                    onClick={() => setSettings({ ...settings, format: fmt })}
                    className={`flex-1 py-2 text-xs font-bold rounded-md transition-colors ${
                      settings.format === fmt 
                        ? 'bg-primary text-white shadow' 
                        : 'text-gray-400 hover:text-white'
                    }`}
                  >
                    {fmt.split('/')[1].toUpperCase()}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>

        <div className="mt-auto pt-6 border-t border-gray-700">
           <div className="flex justify-between items-center mb-4">
              <span className="text-gray-400">Gốc:</span>
              <span className="font-mono text-white">{formatBytes(originalFile.size)}</span>
           </div>
           <div className="flex justify-between items-center mb-6">
              <span className="text-gray-400">Kết quả:</span>
              <span className={`font-mono font-bold ${processed && processed.size < originalFile.size ? 'text-green-400' : 'text-yellow-400'}`}>
                {processed ? formatBytes(processed.size) : '...'}
              </span>
           </div>

           <Button 
            onClick={handleDownload} 
            disabled={!processed} 
            className="w-full"
           >
            Tải xuống
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
            </svg>
           </Button>
        </div>
      </div>

      {/* Preview */}
      <div className="flex-1 bg-gray-900/50 rounded-2xl flex items-center justify-center p-4 border border-dashed border-gray-700 relative overflow-hidden group">
        {!processed && isProcessing && (
          <div className="absolute inset-0 flex items-center justify-center bg-dark/50 z-10">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          </div>
        )}
        {processed ? (
          <div className="relative max-w-full max-h-full">
            <img 
              src={processed.url} 
              alt="Processed" 
              className="max-w-full max-h-[70vh] object-contain rounded-lg shadow-2xl" 
            />
            <div className="absolute bottom-4 right-4 bg-black/70 backdrop-blur text-white text-xs px-2 py-1 rounded">
              {processed.width} x {processed.height} px
            </div>
          </div>
        ) : (
           <span className="text-gray-500">Đang xử lý...</span>
        )}
      </div>
    </div>
  );
};

