            <p className="text-xs text-gray-400 mb-6 leading-relaxed">Sử dụng Gemini 2.5 Flash Image để tái tạo và nâng cấp hình ảnh.</p>

            <div className="space-y-4">
              <div className="flex gap-2 p-1 bg-gray-900 rounded-lg border border-gray-800">
                <button
                  onClick={() => setMode('restore')}
                  className={`flex-1 py-2 text-xs font-bold rounded-md transition-all ${mode === 'restore' ? 'bg-primary text-white shadow ring-1 ring-primary' : 'text-gray-400 hover:text-gray-200 hover:bg-white/5'}`}
                >
                  Phục hồi & Nét
                </button>
                <button
                  onClick={() => setMode('creative')}
                  className={`flex-1 py-2 text-xs font-bold rounded-md transition-all ${mode === 'creative' ? 'bg-purple-600 text-white shadow ring-1 ring-purple-500' : 'text-gray-400 hover:text-gray-200 hover:bg-white/5'}`}
