          </div>

          <div className="h-1/2 bg-gray-900/50 rounded-xl p-4 border border-gray-700 border-dashed relative flex flex-col items-center justify-center group overflow-hidden">
             <span className="absolute top-3 left-3 bg-gradient-to-r from-primary to-purple-600 text-white text-[10px] font-bold px-2 py-1 rounded shadow-lg z-10">KẾT QUẢ AI</span>
             {isProcessing ? (
               <div className="flex flex-col items-center gap-3">
                 <div className="w-8 h-8 border-2 border-purple-500 border-t-transparent rounded-full animate-spin"></div>
