            >
              {isProcessing ? 'Đang phân tích...' : 'Bắt đầu xử lý'}
            </Button>

            {resultUrl && (
              <Button onClick={handleDownload} variant="ghost" className="w-full border border-gray-300 dark:border-gray-600 hover:border-gray-400">
                Tải xuống ảnh AI
              </Button>
            )}
          </div>
       </div>

       {/* Comparison View (Right) */}
       <div className="lg:col-span-8 h-full flex flex-col gap-4">
          <div className="h-1/2 bg-gray-100 dark:bg-gray-900/50 rounded-xl p-4 border border-gray-300 dark:border-gray-700 relative flex flex-col group overflow-hidden">
            <span className="absolute top-3 left-3 bg-white/90 dark:bg-black/70 backdrop-blur text-gray-900 dark:text-white text-[10px] font-bold px-2 py-1 rounded border border-gray-200 dark:border-white/10 z-10 shadow-sm">GỐC</span>
            <div className="flex-1 flex items-center justify-center overflow-hidden">
               <img 
                  src={URL.createObjectURL(originalFile)} 
                  alt="Original" 
                  className="max-h-full max-w-full object-contain transition-transform duration-500 group-hover:scale-[1.02]" 
                  onLoad={(e) => URL.revokeObjectURL((e.target as HTMLImageElement).src)}
                />
